  while(i<ms && n<5){
    int s=i; while(mp[i]&&i<ms)i++;
    printf("key: %s\n",mp+s);
    i++; /* null */
    int s2=i; while(mp[i]&&i<ms)i++;
    printf("  shape: %s\n",mp+s2);
    i++;
    i+=4; /* dtype */
